{
  "bill": {
    "slug": "s3596-119",
    "name": "Stronger Start for Working Families Act (S. 3596)",
    "status": "Introduced in Senate · Hassan / Young",
    "pages": 2,
    "analyzed": "Full bill (Section 2)",
    "analysisDate": "2026-07-31",
    "sourceUrl": "https://www.congress.gov/bill/119th-congress/senate-bill/3596"
  },
  "provisions": [
    {
      "title": "Section 2",
      "heading": "Earned income threshold for the refundable child tax credit: $3,000 → $1",
      "quote": "Section 24(d)(1)(B)(i) of the Internal Revenue Code of 1986 is amended by striking ``$3,000'' and inserting ``$1''. … Section 24(h) of such Code is amended by striking paragraph (6). … The amendments made by this section shall apply to taxable years beginning after December 31, 2025.",
      "context": "Under current law the refundable portion of the child tax credit (the additional child tax credit) phases in at 15 percent of earned income above a threshold — $3,000 in the permanent statute at §24(d)(1)(B)(i), overridden to $2,500 by §24(h)(6). The bill lowers the permanent threshold to $1 and strikes the $2,500 override, so the phase-in starts from the first dollar of earned income. The 15 percent phase-in rate and the refundable cap are unchanged; the change takes effect for taxable years beginning after December 31, 2025.",
      "goals": [
        "Extend the refundable child tax credit to working families with the lowest earnings by starting the phase-in at the first dollar earned.",
        "Raise refund amounts for families whose earnings currently fall at or below the phase-in threshold."
      ],
      "effects": [
        {
          "mechanism": "Phase-in floor",
          "text": "Families with earned income below the current $2,500 threshold become newly eligible for a refundable credit; every family whose refundable credit is limited by the earnings formula gains up to 15 percent of $2,499 (about $375), holding the rate and cap fixed."
        },
        {
          "mechanism": "Filing requirement",
          "text": "The newly eligible population is concentrated among very-low-income households, many of whom are not currently required to file; claiming the credit requires filing a return, so realized take-up depends on filing behavior, not only on eligibility."
        },
        {
          "mechanism": "Unchanged parameters",
          "text": "The $2,200 credit amount, the refundable cap, and the 15 percent phase-in rate are untouched — the provision changes who reaches a given refundable amount at what earnings level, not the credit's ceiling."
        }
      ],
      "barriers": [
        {
          "actor": "IRS",
          "text": "The threshold change must land in TY2026 forms, instructions, and e-file schema for the 2027 filing season; the conforming strike of §24(h)(6) also touches guidance that currently cites the $2,500 figure."
        },
        {
          "actor": "Outreach / VITA",
          "text": "Reaching newly eligible non-filers is an outreach problem: the households gaining eligibility are those least connected to the filing system."
        }
      ],
      "metrics": [
        {
          "kind": "Direct implementation/outcome",
          "category": "operational",
          "layer": "participation",
          "text": "IRS Statistics of Income, Individual Income Tax Returns (Publication 1304 line-item tables): number of returns claiming the additional child tax credit and total ACTC dollars, TY2027 versus prior years.",
          "series_hint": "irs.soi.additional_child_tax_credit_returns",
          "rationale": "The provision operates entirely through the ACTC formula, so ACTC returns and dollars are the most direct administrative readout: if the threshold change does anything, it must appear here first. Official, first-print resolvable from a fixed IRS publication. The registered conditional pair targets TY2027, matching its policy premise. Known weakness: SOI line-item tables publish with roughly a two-year lag, so TY2027 resolves in 2029; considered the weekly Filing Season Statistics as a faster proxy and rejected it because it does not break out the ACTC line.",
          "stances": [
            {
              "goal": 0,
              "stance": "serves"
            },
            {
              "goal": 1,
              "stance": "serves"
            }
          ]
        },
        {
          "kind": "Downstream outcome",
          "category": "intended",
          "layer": "outcome",
          "text": "Census Bureau Supplemental Poverty Measure, child poverty rate — the SPM accounts for refundable credits, so a phase-in change for the lowest earners shows up here if realized take-up is material.",
          "series_hint": "census.spm.child_poverty_rate",
          "rationale": "Selected because it is the outcome the goal actually claims (resources of the lowest-earning families) and because the SPM is already a live Thesis registry series with existing forecast cells. The conditional pair targets CY2027 so its outcome can reflect the provision's TY2027 application. Thesis commits the conservative 2028-08-01 through 2028-12-31 release window and 2028-12-31 resolve-by deadline; the registered Census announcement authenticates revised-methodology identity only and establishes neither timing value. The pair is non-exhaustive: an intermediate enacted threshold satisfies neither arm. Known weakness: attribution is noisy — a sub-$400-per-family change sits inside the SPM's year-to-year movement, so this metric is informative in the enacted-versus-unchanged-current-law pair, not as a standalone level.",
          "stances": [
            {
              "goal": 0,
              "stance": "serves"
            },
            {
              "goal": 1,
              "stance": "orthogonal"
            }
          ]
        },
        {
          "kind": "Honest gap",
          "category": "operational",
          "layer": "participation",
          "text": "No official series separates ACTC claims by earnings band at the threshold margin in a timely publication; SOI tabulations by AGI band are the closest proxy and lag by about two years.",
          "series_hint": "",
          "rationale": "Recorded as a gap rather than omitted: the sharpest test of this provision would be claims among families earning under $2,500, and no official publication isolates that band on a useful timeline. Stating the missing series is part of the analysis — it is the demand signal a registry would need to close.",
          "stances": [
            {
              "goal": 0,
              "stance": "orthogonal"
            },
            {
              "goal": 1,
              "stance": "orthogonal"
            }
          ]
        }
      ],
      "conditionals": [
        "P(IRS SOI TY2027 ACTC returns and dollars | §24(d)(1)(B)(i) threshold ≤ $1 for TY2027 vs unchanged $2,500 current-law threshold for TY2027; an intermediate enacted threshold is outside both arms)",
        "P(Census SPM child poverty rate for CY2027 | §24(d)(1)(B)(i) threshold ≤ $1 for TY2027 vs unchanged $2,500 current-law threshold for TY2027; an intermediate enacted threshold is outside both arms)"
      ],
      "compute": [
        {
          "model": "policyengine-us",
          "reform": {
